<?php /** One recipe (screen recipe-view). Data: full, siteId, sites, seesCost, mayWrite, mayDelete, deletable, tab, trail, tz, back, notice */
$r = $full['recipe']; $id = (int) $r['recipe_id']; $v = $full['version']; $color = RECIPE_KIND_COLOR[$r['kind']] ?? 'secondary';
$hasDraft = false; foreach ($full['versions'] as $x) { if ($x['status'] === 'draft') { $hasDraft = $x; } }
$here = here_url();
$actions = '';
if ($mayWrite) {
    $actions .= hx_link(with_back('/recipes/' . $id . '/edit', $here), '<i class="feather-edit-2 me-1"></i>Edit', 'btn btn-light-brand btn-touch', 'id="recipe-view-edit"');
    if ($hasDraft) { $actions .= ' ' . hx_link('/recipes/versions/' . (int) $hasDraft['recipe_version_id'], '<i class="feather-edit-3 me-1"></i>Edit the draft', 'btn btn-warning btn-touch', 'id="recipe-view-edit-draft"'); }
    else { $actions .= ' <form method="post" action="/recipes/versions/draft.php" hx-post="/recipes/versions/draft.php" hx-target="#flash" class="d-inline" id="new-draft-form">' . csrf_field() . '<input type="hidden" name="recipe" value="' . $id . '"><button type="submit" class="btn btn-light-brand btn-touch" id="recipe-view-new-draft"><i class="feather-copy me-1"></i>New draft</button></form>'; }
    if ($seesCost) { $actions .= ' ' . hx_link(with_back('/recipes/' . $id . '/what-if', $here), 'What if', 'btn btn-light btn-touch', 'id="recipe-view-what-if"') . ' ' . hx_link(with_back('/recipes/' . $id . '/cost', $here), 'Cost history', 'btn btn-light btn-touch', 'id="recipe-view-cost-history"'); }
}
?>
<?= view('shared/header.php', ['id' => 'recipe-view', 'title' => $r['name'], 'crumbs' => [['Home', '/'], ['Recipes', '/recipes/'], [$r['name'], null]], 'back' => $back, 'action' => $actions]) ?>
<div class="main-content" id="recipe-view-content">
    <?= view('shared/notice.php', ['notice' => $notice]) ?>
    <div class="card mb-3" id="recipe-view-header"><div class="card-body d-flex flex-wrap gap-3 align-items-start">
        <?php if (!empty($r['photo_attachment_id'])): ?><img class="rounded" src="/files/<?= (int) $r['photo_attachment_id'] ?>" alt="" width="96" height="96" id="recipe-view-photo"><?php else: ?><span class="avatar-text avatar-xl rounded bg-soft-<?= $color ?> text-<?= $color ?>"><i class="feather-<?= $r['kind'] === 'prep' ? 'coffee' : 'book-open' ?>"></i></span><?php endif; ?>
        <div class="flex-grow-1 min-w-0">
            <div class="chip-row mb-1"><span class="badge bg-soft-<?= $color ?> text-<?= $color ?>" id="recipe-view-kind"><?= e(RECIPE_KINDS[$r['kind']]) ?></span><?php if ($r['category']): ?><span class="badge bg-soft-light text-dark border"><?= e($r['category']) ?></span><?php endif; ?><?php if (!$r['active']): ?><span class="badge bg-soft-dark text-dark" id="recipe-view-archived">archived</span><?php endif; ?><?php foreach ($r['allergens'] as $a): ?><span class="badge bg-soft-light text-dark border recipe-allergen"><?= e($a) ?></span><?php endforeach; ?></div>
            <div class="fs-12 text-muted" id="recipe-view-facts"><?= e($r['code']) ?><?php if ($r['output_ingredient']): ?> · makes <?= hx_link('/ingredients/' . (int) $r['output_ingredient_id'], e($r['output_ingredient'])) ?><?php endif; ?><?php if ($r['portion_qty']): ?> · one portion is <?= e(ri_fmt($r['portion_qty'])) ?> <?= e($r['portion_unit_code']) ?><?php endif; ?> · costed as of <?= e(format_date($full['as_of'])) ?><?php foreach ($sites as $s): if ((int) $s['scope_id'] === $siteId): ?> at <?= e($s['name']) ?><?php endif; endforeach; ?></div>
            <div class="mt-2"><?= view('recipes/partials/version-strip.php', ['versions' => $full['versions'], 'chosen' => $v ? (int) $v['recipe_version_id'] : null, 'recipeId' => $id]) ?></div>
            <?php if (count($sites) > 1): ?><form method="get" action="/recipes/<?= $id ?>" class="mt-2 d-flex gap-2 align-items-center" id="recipe-view-site-form" hx-get="/recipes/<?= $id ?>" hx-target="#page-content" hx-trigger="change"><?php if ($v): ?><input type="hidden" name="version" value="<?= (int) $v['recipe_version_id'] ?>"><?php endif; ?><label class="fs-12 text-muted" for="recipe-view-site">Cost at</label><select name="site" id="recipe-view-site" class="form-select form-select-sm w-auto"><?php foreach ($sites as $s): ?><option value="<?= (int) $s['scope_id'] ?>" <?= (int) $s['scope_id'] === $siteId ? 'selected' : '' ?>><?= e($s['name']) ?></option><?php endforeach; ?></select><input type="date" name="as_of" value="<?= e($full['as_of']) ?>" class="form-control form-control-sm w-auto" id="recipe-view-as-of" aria-label="As of"></form><?php endif; ?>
        </div>
        <?php if ($mayWrite): ?><div class="d-flex flex-column gap-2">
            <form method="post" action="/recipes/archive.php" hx-post="/recipes/archive.php" hx-target="#flash" hx-confirm="<?= $r['active'] ? 'Archive' : 'Restore' ?> <?= e($r['name']) ?>?" id="archive-form"><?= csrf_field() ?><input type="hidden" name="recipe" value="<?= $id ?>"><input type="hidden" name="archived" value="<?= $r['active'] ? 'yes' : 'no' ?>"><button type="submit" class="btn btn-light btn-touch w-100" id="recipe-view-archive"><?= $r['active'] ? 'Archive' : 'Restore' ?></button></form>
            <?php if ($mayDelete): ?><form method="post" action="/recipes/delete.php" hx-post="/recipes/delete.php" hx-target="#flash" hx-confirm="Delete <?= e($r['name']) ?>? This cannot be undone." id="delete-form"><?= csrf_field() ?><input type="hidden" name="recipe" value="<?= $id ?>"><button type="submit" class="btn btn-outline-danger btn-touch w-100" id="recipe-view-delete">Delete</button></form><?php elseif ($deletable !== null && has_right('records.delete')): ?><div class="fs-11 text-muted" id="recipe-view-undeletable">Cannot delete: <?= e($deletable) ?></div><?php endif; ?>
        </div><?php endif; ?>
    </div></div>
    <div class="row g-3">
        <div class="col-lg-8">
            <div class="card mb-3" id="recipe-lines"><div class="card-header d-flex justify-content-between align-items-center"><h5 class="card-title mb-0">Lines<?= $v ? ' — v' . (int) $v['version_no'] . ($v['status'] === 'draft' ? ' (draft)' : '') : '' ?></h5><?php if ($v && $v['status'] === 'draft' && $mayWrite): ?><?= hx_link('/recipes/versions/' . (int) $v['recipe_version_id'], 'Edit the draft', 'btn btn-sm btn-warning') ?><?php endif; ?></div>
                <div class="card-body p-0"><?= view('recipes/partials/lines-table.php', ['lines' => $full['lines'], 'cost' => $full['cost'], 'seesCost' => $seesCost, 'versionId' => $v ? (int) $v['recipe_version_id'] : null]) ?></div>
                <?php if (!$seesCost): ?><div class="card-footer fs-12 text-muted" id="recipe-cost-withheld">Cost is withheld from you here.</div><?php endif; ?></div>
            <div class="card mb-3" id="recipe-method"><div class="card-header"><h5 class="card-title mb-0">Method</h5></div><div class="card-body"><?php if ($r['method']): foreach (preg_split('/\n{2,}/', (string) $r['method']) as $p): ?><p><?= nl2br(e($p)) ?></p><?php endforeach; else: ?><span class="text-muted">No method written.</span><?php endif; ?></div></div>
            <?php if ($full['tree'] !== []): ?><div class="card mb-3" id="recipe-tree"><div class="card-header"><h5 class="card-title mb-0">The tree</h5></div><div class="card-body"><?= view('recipes/partials/tree.php', ['nodes' => $full['tree']]) ?>
                <?php if ($full['leaves'] !== []): ?><div class="fs-12 text-muted mt-2 border-top pt-2" id="recipe-leaves">One batch uses, in all: <?php $parts = []; foreach ($full['leaves'] as $lf) { $parts[] = e(ri_fmt($lf['qty_base'], $lf['base_unit_code'] === 'each' ? 0 : 1) . ' ' . $lf['base_unit_code'] . ' of ' . $lf['name']); } echo implode(', ', $parts); ?></div><?php endif; ?></div></div><?php endif; ?>
        </div>
        <div class="col-lg-4">
            <?php if ($v): ?><div class="card mb-3" id="recipe-batch"><div class="card-header"><h5 class="card-title mb-0">Batch</h5></div><div class="card-body fs-12">
                <div><strong>One batch makes</strong> <?= e(ri_fmt($v['batch_yield_qty'], 4)) ?> <?= e($v['batch_yield_unit_code'] ?? ((float) $v['batch_yield_qty'] === 1.0 ? 'portion' : 'portions')) ?></div>
                <div><strong>Expected loss</strong> <?= e(ri_fmt($v['expected_loss_pct'], 2)) ?> %<?php if ((float) $v['expected_loss_pct'] > 0 && $v['batch_yield_unit_code']): ?> — <?= e(ri_fmt($v['batch_yield_qty'], 4)) ?> <?= e($v['batch_yield_unit_code']) ?> makes <?= e(ri_fmt((float) $v['batch_yield_qty'] * (1 - (float) $v['expected_loss_pct'] / 100), 4)) ?> <?= e($v['batch_yield_unit_code']) ?><?php endif; ?></div>
                <?php if ($v['change_note']): ?><div class="text-muted mt-1"><?= e($v['change_note']) ?></div><?php endif; ?>
                <?php if ($mayWrite && $v['status'] === 'active' && $v['effective_to'] === null): ?><form method="post" action="/recipes/versions/retire.php" hx-post="/recipes/versions/retire.php" hx-target="#flash" hx-confirm="Retire v<?= (int) $v['version_no'] ?>? The recipe leaves the menu after the date." class="mt-2 d-flex gap-2" id="retire-form"><?= csrf_field() ?><input type="hidden" name="version" value="<?= (int) $v['recipe_version_id'] ?>"><input type="date" name="effective_to" value="<?= date('Y-m-d') ?>" class="form-control form-control-sm" id="retire-form-field-effective-to" aria-label="Retire after"><button type="submit" class="btn btn-sm btn-light" id="recipe-view-retire">Retire after</button></form><?php endif; ?>
            </div></div><?php endif; ?>
            <div class="card mb-3" id="recipe-menu-items"><div class="card-header"><h5 class="card-title mb-0">Menu items</h5></div><div class="card-body p-0"><?= view('recipes/partials/menu-items-tab.php', ['items' => $full['menu_items'], 'seesCost' => $seesCost]) ?></div></div>
            <div class="card mb-3" id="recipe-used-in"><div class="card-header"><h5 class="card-title mb-0">Used in</h5></div><div class="card-body p-0"><?= view('recipes/partials/used-in.php', ['rows' => $full['used_in']]) ?></div></div>
            <div class="card mb-3" id="recipe-notes"><div class="card-header"><h5 class="card-title mb-0">Notes</h5></div><div class="card-body">
                <?php foreach ($full['notes'] as $n): ?><div class="border-bottom py-1 fs-12" id="note-<?= (int) $n['note_id'] ?>"><?= e($n['body']) ?> <span class="text-muted">— <?= e($n['display_name'] ?? '') ?></span></div><?php endforeach; ?>
                <?php if ($full['notes'] === []): ?><span class="text-muted fs-12">No notes.</span><?php endif; ?>
                <?php if (has_right('notes.write')): ?><form method="post" action="/notes/add.php" hx-post="/notes/add.php" hx-target="#flash" class="mt-2 d-flex gap-2" id="note-form"><?= csrf_field() ?><input type="hidden" name="record_type" value="recipe"><input type="hidden" name="record_id" value="<?= $id ?>"><input type="text" name="body" class="form-control btn-touch" placeholder="A note" maxlength="2000" id="note-form-field-body"><button type="submit" class="btn btn-light-brand btn-touch">Add</button></form><?php endif; ?>
            </div></div>
            <div class="card mb-3" id="recipe-trail"><div class="card-header"><h5 class="card-title mb-0">Trail</h5></div><div class="card-body fs-12">
                <?php foreach (array_slice($trail, 0, 20) as $a): ?><div class="border-bottom py-1" id="trail-row-<?= (int) $a['activity_id'] ?>"><span class="text-muted"><?= e(format_ts($a['occurred_at'], $tz)) ?></span> <?= e($a['action']) ?> <span class="text-muted">— <?= e($a['actor_name'] ?? 'system') ?></span></div><?php endforeach; ?>
                <?php if ($trail === []): ?><span class="text-muted">Nothing yet.</span><?php endif; ?>
            </div></div>
        </div>
    </div>
</div>
